Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXE = 1000007;
const int MAXN = 1000;

char s1[15][15], s2[15][15];
int id[15][15], cnt;
int S, T, limitT, n, zx, zy;
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};

inline bool inside(int x, int y) {
    return x >= 0 && y >= 0 && x < n && y < n && s1[x][y] >= '0' && s1[x][y] <= '9';
}

int to[MAXE], nxtEdge[MAXE], cap[MAXE], head[MAXN], tot;

void addEdge(int u, int v, int c) {
    to[tot] = v;
    nxtEdge[tot] = head[u];
    cap[tot] = c;
    head[u] = tot++;

    to[tot] = u;
    nxtEdge[tot] = head[v];
    cap[tot] = 0;
    head[v] = tot++;
}

int q1[MAXE], q2[MAXE];
int h1, t1, h2, t2;
int d1[15][15], d2[15][15];

void buildNetwork(int x, int y) {
    if (s2[x][y] != 0) {
        addEdge(id[x][y] + cnt, T, s2[x][y] - '0');
    }
    if (s1[x][y] == '0') return;
    addEdge(S, id[x][y], s1[x][y] - '0');
    if (s2[x][y] != 0) {
        addEdge(id[x][y], id[x][y] + cnt, 10);
    }

    int sx = x, sy = y;
    h1 = t1 = h2 = t2 = 0;
    q1[t1++] = x;
    q1[t1++] = y;
    q2[t2++] = zx;
    q2[t2++] = zy;

    int up1 = t1, up2 = t2;
    memset(d1, -1, sizeof(d1));
    memset(d2, -1, sizeof(d2));
    d1[x][y] = 0;
    d2[zx][zy] = 0;

    int nx, ny;
    while (h1 < t1) {
        while (h1 < up1) {
            x = q1[h1++];
            y = q1[h1++];
            if (d2[x][y] >= 0) continue;

            for (int i = 0; i < 4; ++i) {
                nx = x + dx[i];
                ny = y + dy[i];
                if (inside(nx, ny) && d1[nx][ny] < 0) {
                    d1[nx][ny] = d1[x][y] + 1;
                    if (d1[nx][ny] > limitT) break;
                    if (d2[nx][ny] >= 0) continue;
                    q1[t1++] = nx;
                    q1[t1++] = ny;
                    if (s2[nx][ny] != '0') {
                        addEdge(id[sx][sy], id[nx][ny] + cnt, 10);
                    }
                }
            }
        }
        up1 = t1;

        while (h2 < up2) {
            x = q2[h2++];
            y = q2[h2++];
            for (int i = 0; i < 4; ++i) {
                nx = x + dx[i];
                ny = y + dy[i];
                if (inside(nx, ny) && d2[nx][ny] < 0) {
                    d2[nx][ny] = d2[x][y] + 1;
                    q2[t2++] = nx;
                    q2[t2++] = ny;
                }
            }
        }
        up2 = t2;
    }
}

int level[MAXN], it[MAXN];

bool bfsLevel() {
    fill(level, level + T + 1, -1);
    queue<int> q;
    level[S] = 0;
    q.push(S);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int e = head[u]; e != -1; e = nxtEdge[e]) {
            int v = to[e];
            if (cap[e] > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[T] != -1;
}

int dfs(int u, int f) {
    if (u == T) return f;

    for (int &e = it[u]; e != -1; e = nxtEdge[e]) {
        int v = to[e];
        if (cap[e] > 0 && level[v] == level[u] + 1) {
            int pushed = dfs(v, min(f, cap[e]));
            if (pushed) {
                cap[e] -= pushed;
                cap[e ^ 1] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int ans = 0;
    while (bfsLevel()) {
        for (int i = 0; i <= T; ++i) it[i] = head[i];
        while (int pushed = dfs(S, 10000000)) ans += pushed;
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> limitT;
    for (int i = 0; i < n; ++i) cin >> s1[i];
    for (int i = 0; i < n; ++i) cin >> s2[i];

    memset(head, -1, sizeof(head));
    tot = 0;
    memset(id, -1, sizeof(id));
    cnt = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (s1[i][j] == 'Z') {
                zx = i;
                zy = j;
            } else if (inside(i, j)) {
                id[i][j] = ++cnt;
            }
        }
    }

    S = 0;
    T = 2 * cnt + 1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (inside(i, j)) buildNetwork(i, j);
        }
    }

    cout << maxFlow() << '\n';
    return 0;
}
